return {
	minX: data.filter(${comparisonFn} > 0).reduce((a, c) => Math.min(a, c.x), Infinity),
	maxX: data.filter(${comparisonFn} < 0).reduce((a, c) => Math.max(a, c.x), -Infinity),
	minY: data.filter(${comparisonFn} > 0).reduce((a, c) => Math.min(a, c.y), Infinity),
	maxY: data.filter(${comparisonFn} < 0).reduce((a, c) => Math.max(a, c.y), -Infinity)
}

